package me.xjanua.aitranswatch.service;
import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import me.xjanua.aitranswatch.dto.driver.*; import me.xjanua.aitranswatch.enums.DriverStatus; import me.xjanua.aitranswatch.model.Driver; import me.xjanua.aitranswatch.repository.DriverRepository;
@Service @Transactional
public class DriverService {
 private final DriverRepository repository; public DriverService(DriverRepository repository){this.repository=repository;}
 @Transactional(readOnly=true) public Page<DriverResponse> list(String search,DriverStatus status,Pageable pageable){Page<Driver> p;boolean has=search!=null&&!search.isBlank();if(status!=null&&has)p=repository.findByStatusAndEmployeeCodeContainingIgnoreCaseOrStatusAndLicenseNumberContainingIgnoreCase(status,search,status,search,pageable);else if(status!=null)p=repository.findByStatus(status,pageable);else if(has)p=repository.findByEmployeeCodeContainingIgnoreCaseOrLicenseNumberContainingIgnoreCase(search,search,pageable);else p=repository.findAll(pageable);return p.map(this::toResponse);}
 @Transactional(readOnly=true) public DriverResponse get(UUID id){return toResponse(entity(id));}
 public DriverResponse create(DriverRequest r){if(repository.existsByEmployeeCodeIgnoreCase(r.employeeCode()))throw conflict("Mã nhân viên đã tồn tại");if(repository.existsByLicenseNumberIgnoreCase(r.licenseNumber()))throw conflict("Số GPLX đã tồn tại");return toResponse(repository.save(new Driver(r.employeeCode(),r.licenseNumber(),r.licenseClass(),r.licenseExpiryDate(),r.status(),r.safetyScore(),r.totalDistanceKm())));}
 public DriverResponse update(UUID id,DriverRequest r){Driver e=entity(id);if(!e.getEmployeeCode().equalsIgnoreCase(r.employeeCode())&&repository.existsByEmployeeCodeIgnoreCase(r.employeeCode()))throw conflict("Mã nhân viên đã tồn tại");if(!e.getLicenseNumber().equalsIgnoreCase(r.licenseNumber())&&repository.existsByLicenseNumberIgnoreCase(r.licenseNumber()))throw conflict("Số GPLX đã tồn tại");e.update(r.employeeCode(),r.licenseNumber(),r.licenseClass(),r.licenseExpiryDate(),r.status(),r.safetyScore(),r.totalDistanceKm());return toResponse(e);}
 public void suspend(UUID id){entity(id).suspend();} private Driver entity(UUID id){return repository.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy tài xế"));}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private DriverResponse toResponse(Driver e){return new DriverResponse(e.getId(),e.getEmployeeCode(),e.getLicenseNumber(),e.getLicenseClass(),e.getLicenseExpiryDate(),e.getStatus(),e.getSafetyScore(),e.getTotalDistanceKm());}
}
